customCSS:
.t, .history { color: #878787; }
.join { color: #5f8700; }
.part, .quit { color: #878787; }
.kick, .error { color: #d70000; }
.notice { color: #d70087; }
.action { color: #d70087; }
.mode, .nick, .topic, .server { color: #005f87; }
.highlight { color: #444444; background-color: #ffff5f; border-left: 3px solid #d70087; padding-left: 8px; }
.reply { color: #878787; border-left: 2px solid #0087af; padding-left: 6px; }
.oper { color: #eeeeee; background-color: #d70087; }
.reactions { color: #0087af; background-color: #e4e4e4; }
.card { background-color: #e4e4e4; border-color: #878787; }
.card-title { color: #0087af; }
.card-desc { color: #878787; }
.daychange { color: #878787; border-color: #e4e4e4; }
